			function setSprtPsbltyYN(sTrprBrthYmd) {

			    if(ValueUtil.isNull(sTrprBrthYmd)) {
			        return;
			    } else {
			        sTrprBrthYmd = sTrprBrthYmd.replace("-", "").replace("-", "");
			    }

			    sIntrlAge = Math.floor(DateUtil.getDiffDay(sTrprBrthYmd, vsToday) / 365);

			    sSprtPsbltyYN = "N";

			    if(untTaskwk == "U05") {
			        sSprtPsbltyYN = "Y";

			    } else if(untTaskwk == "U07") {
			        if(cpr.utils.Util.toNumber(sIntrlAge) > 9 && cpr.utils.Util.toNumber(sIntrlAge) < 18) {
			            sSprtPsbltyYN = "Y";
			        }

			    } else if(untTaskwk == "U08") {
			        if(cpr.utils.Util.toNumber(sIntrlAge) > 12 && cpr.utils.Util.toNumber(sIntrlAge) < 20) {
			            sSprtPsbltyYN = "Y";
			        }

			    } else if(untTaskwk == "U10") {
			        if(cpr.utils.Util.toNumber(sIntrlAge) > 15 && cpr.utils.Util.toNumber(sIntrlAge) < 24) {
			            sSprtPsbltyYN = "Y";
			        }

			    } else {
			        if(cpr.utils.Util.toNumber(sIntrlAge) > 8 && cpr.utils.Util.toNumber(sIntrlAge) < 25) {
			            sSprtPsbltyYN = "Y";
			        }
			    }

			    if(sSprtPsbltyYN != "Y") {
			        app.lookup("comformtitle12").useInfo     = true;
			        app.lookup("comformtitle12").InfoMessage = "사례관리 대상 연령이 맞는지 확인해 주세요.";
			    } else {
			        app.lookup("comformtitle12").useInfo     = false;
			        app.lookup("comformtitle12").InfoMessage = "";
			    }
			}

