			/*
			 * 루트 컨테이너에서 property-change 이벤트 발생 시 호출.
			 * 앱의 속성이 변경될 때 발생하는 이벤트 입니다.
			 */
			function onBodyPropertyChange( /* cpr.events.CPropertyChangeEvent */ e) {
				console.log("property");
			    if (e.property == "type") {
			        if (e.newValue == "READ") {
			            setDtlCrud("READ");
			        } else if (e.newValue == "CREATE") {
			            // 공통코드조회
			            callCommCd();

			            // Step조회
			            setStepNocs();

			            setDtlCrud("CREATE");

			            app.lookup("sipb6").focus();
			        }
			    } else if (e.property == "data") {
			        app.lookup("dmParam") .build(e.newValue);

			        // 공통코드조회
			        callCommCd();

			        // Step조회
			        setStepNocs();

			        doList();
			    }
			}

			/*
			 * 사용자 정의 컨트롤에서 stepItem-click 이벤트 발생 시 호출.
			 * 스텝 아이템 클릭 이벤트
			 */
			function onCmniconstepprogress1StepItemClick( /* cpr.events.CAppEvent */ e) {

			    var cmnStepProgress  = e.control;

			    var vsBeforeStepIdx  = cmnStepProgress.step;
			    var vsBeforeStepInfo = cmnStepProgress.getStepInfo(vsBeforeStepIdx);
			    var vsBeforeStepVal  = vsBeforeStepInfo["stepValue"];

			    var vnNextStepIdx = e.userData["stepIndex"];
			    var vsNextStepVal = e.userData["stepValue"];
			    var dsDetailInfo  = app.lookup("dsDetailInfo");
			    var caseMngNo     = dsDetailInfo.getValue(0, "CASE_MNG_NO");
			    var caseMngOdrno  = dsDetailInfo.getValue(0, "CASE_MNG_ODRNO");

			    var nStep      = 1;
			    var nStepOschl = 1;

			    if(untTaskwk == "U03" || untTaskwk == "U04" || untTaskwk == "U05") {
			        nStepOschl = vnNextStepIdx;
			    } else {
			        nStep      = vnNextStepIdx;
			    }

			    //사후관리여부 값설정
			    sAftfctMngYn  = util.DataSet.getValue(app, "dsCaseMngNocs", 0, "AFTFCT_MNG_YN"); //사후관리여부

			    //스텝별권한여부 값설정
			    getStepAuthrtYn(nStep, nStepOschl);

			    if (vsBeforeStepIdx != vnNextStepIdx) {
			        // 저장 동작중이라면 confirm, 추후 각 컨텐츠 유효성 체크 필요
			        if (msCrudType != "CREATE" && msCrudType != "READ") {
			            util.Msg.confirm(app, "CRM-M003", vsBeforeStepVal + " 단계", function() {
			//                if(sCaseSttsSeCd != "01") setDtlCrud("READ");
			                setDtlCrud("READ");
			                setStepAcdAttr(vnNextStepIdx);
			                if(vsBeforeStepVal == "사후관리"){
			                    app.lookup("dsPic").revert();
			                }
			                setGrpEnable(caseMngNo, caseMngOdrno, nStepOschl, nStep);

			                return false;
			            }, function() {
			                if(untTaskwk == "U03" || untTaskwk == "U04" || untTaskwk == "U05") {
			                    nStepOschl = vsBeforeStepIdx;
			                } else {
			                    nStep      = vsBeforeStepIdx;
			                }

			                getStepAuthrtYn(nStep, nStepOschl);
			        /* 2023-01-25 YOO.CHI.HOON 수정시 스텝이동전에 취소여서 confrim메세지 띄우고 취소버튼 누른경우 스텝이동없이 */
			//                setGrpEnable(caseMngNo, caseMngOdrno, nStepOschl, nStep);

			                return false;
			            });
			        } else {
			            setStepAcdAttr(vnNextStepIdx);
			        }
			    }

			    //TODO 이승재 변경사항 - 20221223
			    if((untTaskwk == 'U07') && app.lookup("cmnStepProgress").step == 2){
			        app.lookup("btn3").visible = true;
			    } else {
			        app.lookup("btn3").visible = false;
			    }

			    if((untTaskwk == 'U07') && app.lookup("cmnStepProgress").step == 4) {
			        app.lookup("btn4").visible = true;
			    } else {
			        app.lookup("btn4").visible = false;
			    }


			    /* 2023-01-25 YOO.CHI.HOON 수정시 스텝이동전에 취소여서 confrim메세지 띄우고 취소버튼 누른경우 스텝이동없이 */
			    if(msCrudType == "CREATE" || msCrudType == "READ"){
			        setGrpEnable(caseMngNo, caseMngOdrno, nStepOschl, nStep);
			    }
			//        setGrpEnable(caseMngNo, caseMngOdrno, nStepOschl, nStep);
			}

