			/*
			 * "취소" 버튼(btnRestore)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnRestoreClick(/* cpr.events.CMouseEvent */ e){

			    var step  = 1;
			    var step2 = 1;

			    var vcEmbDefInfo = null;

			    if(untTaskwk == "U03" || untTaskwk == "U04" || untTaskwk == "U05") {
			        step2 = app.lookup("cmnStepProgress").step;
			    } else {
			        step  = app.lookup("cmnStepProgress").step;
			    }

			    //사례등록
			    if(step == 1 && step2 == 1) {
			        app.lookup("dsDetailInfo").revert();
			        app.lookup("dsCaseYngbgs").revert();
			        app.lookup("dsPic")       .revert();
			        app.lookup("dsBizReg")    .revert();

			        setDsCaseYngbgsRowCnt();
			        setDsPicRowCnt();
			        setDsBizRegRowCnt();

			        if(vsAppId1 != null) {
			            //업무영역 출력화면에서 데이터셋만 추출하여 revert
			            if(vcEmbDefInfo1.getEmbeddedAppInstance() != null) {
			                vcEmbDefInfo1.getEmbeddedAppInstance().getAllDataControls().forEach(function(ctrl) {
			                    if(ctrl.type == "dataset") {
			                        ctrl.revert();
			                    }
			                });
			            }
			        }
			    } else {
			        //계획
			        if(step == 2 || step2 == 2) {
			            vcEmbDefInfo = vcEmbDefInfo2;
			        }
			        //실행
			        else if(step == 3 || step2 == 3) {
			            vcEmbDefInfo = vcEmbDefInfo3;
			        }
			        //성과관리
			        else if(step == 1 && step2 == 4) {
			            vcEmbDefInfo = vcEmbDefInfo4;
			        }
			        //종결
			        else if(step == 4 || step2 == 5) {
			            vcEmbDefInfo = vcEmbDefInfo5;
			        }
			        //사후관리
			        else if(step == 5 || step2 == 6) {
			            vcEmbDefInfo = vcEmbDefInfo6;
			        }

			        if(vcEmbDefInfo.getEmbeddedAppInstance() != null) {
			            if(vcEmbDefInfo.hasAppMethod("setRevert")) {
			                vcEmbDefInfo.callAppMethod("setRevert");
			            }
			        }
			    }

			    if(msCrudType != "CREATE") {
			        setDtlCrud("READ");
			    } else {
			        setDtlCrud("CREATE");
			    }
			}

