			function onComBtnGrid3Insert(e){

			    var comBtnGrid3 = e.control;

			    var objGrd = app.lookup("grdPic");
			    var objDs  = objGrd.dataSet;

			    var rowIdx = objGrd.getSelectedRow().getIndex();

			    objDs.setValue(rowIdx, "PIC_DSGN_YMD"    , vsToday);
			    objDs.setValue(rowIdx, "UNT_TASKWK_SE_CD", untTaskwk);

			    var nPchprsCnt = 0;

			    for(var i=0; i<objDs.getRowCount(); i++) {
			        if(objDs.getRowState(i) != cpr.data.tabledata.RowState.DELETED) {
			            if(objDs.getValue(i, "PCHPRS_YN") == "Y") {
			                nPchprsCnt++;
			            }
			        }
			    }

			    if(nPchprsCnt == 0) {
			        objDs.setValue(rowIdx, "PCHPRS_YN", "Y");
			    } else {
			        objDs.setValue(rowIdx, "PCHPRS_YN", "N");
			    }

			    objDs.setValue(rowIdx, "REG_AUTHRT_YN"    , "Y"); //등록권한여부
			    objDs.setValue(rowIdx, "PLAN_AUTHRT_YN"   , "Y"); //계획권한여부
			    objDs.setValue(rowIdx, "EXCN_AUTHRT_YN"   , "Y"); //실행권한여부
			    objDs.setValue(rowIdx, "TRMN_AUTHRT_YN"   , "Y"); //종결권한여부
			    objDs.setValue(rowIdx, "AFTFCT_AUTHRT_YN" , "Y"); //사후권한여부
			    objDs.setValue(rowIdx, "OUTC_AUTHRT_YN"   , (untTaskwk == 'U03' || untTaskwk == 'U04' || untTaskwk == 'U05') ? 'Y' : 'N'); //성과권한여부

			    setDsPicRowCnt();
			}

