			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb1Click(e){
			    var sipb1 = e.control;

			    var selIdx = app.lookup("grdBizReg").getSelectedRowIndex();

			    if(msCrudType == "CREATE" || msCrudType == "UPDATE"){

			        //사업등록TAB 실행사업명 검색팝업 호출
			        util.Dialog.open(app, "app/itgcm/bizcmmns/popup/srvcExcnBizListPop", "실행사업 조회", 1280, 700, function(e) {

			            var dialog      = e.control;
			            var voReturnVal = dialog.returnValue;

			            if(!ValueUtil.isNull(voReturnVal)){
			                var dsBizReg = app.lookup("dsBizReg");

			                for(var i=0; i<dsBizReg.getRowCount(); i++) {
			                    var srvcExcnBizNo = dsBizReg.getValue(i, "NEW_SRVC_EXCN_BIZ_NO");
			                    if(srvcExcnBizNo == voReturnVal["SRVC_EXCN_BIZ_NO"]) {
			                        util.Msg.alert(app, "해당 실행사업이 존재합니다.\n다시 선택해주십시요.");
			                        return;
			                    }
			                }

			                //리턴값 설정
			                dsBizReg.setValue(selIdx, "SRVC_BIZ_NO"         , voReturnVal["SRVC_BIZ_NO"]);      //서비스사업번호
			                dsBizReg.setValue(selIdx, "SRVC_BIZ_NM"         , voReturnVal["SRVC_BIZ_NM"]);      //서비스사업명
			                dsBizReg.setValue(selIdx, "BIZ_YR"              , voReturnVal["BIZ_YR"]);           //사업연도
			                dsBizReg.setValue(selIdx, "BIZ_CL_SE_CD"        , voReturnVal["BIZ_CL_SE_CD"]);     //사업분류구분코드
			                dsBizReg.setValue(selIdx, "NEW_SRVC_EXCN_BIZ_NO", voReturnVal["SRVC_EXCN_BIZ_NO"]); //실행사업번호
			                dsBizReg.setValue(selIdx, "NEW_SRVC_EXCN_BIZ_NM", voReturnVal["SRVC_EXCN_BIZ_NM"]); //실행사업명
			                dsBizReg.setValue(selIdx, "EXCN_BIZ_CL_SE_CD"	, voReturnVal["EXCN_BIZ_CL_SE_CD"]); //실행사업명
			                dsBizReg.setValue(selIdx, "BIZ_BGNG_YMD"        , voReturnVal["BIZ_BGNG_YMD"]);     //사업시작일자
			                dsBizReg.setValue(selIdx, "BIZ_END_YMD"         , voReturnVal["BIZ_END_YMD"]);      //사업종료일자

							if("U02" == untTaskwk) {
								cysnetCnctrClinic(p_probmSttsMlsfcSeCd, voReturnVal["EXCN_BIZ_CL_SE_CD"]);
							}
			                util.Control.redraw(app, "grpContsDef");
			                util.Control.redraw(app, "grp12");
			            }
			        });
			    }
			}

