			/**
			 * 청소년상담복지센터 전용
			 * 청소년상태중분류 : 자살, 비자살적 자해 && 사업목록내 집중클리닉 포함 시
			 * embeded 에 집중 심리클리닉 사전검사 탭 추가.
			 * data1 = probmSttsMlsfcSeCd (청소년상태 중분류)
			 * data2 = 사업분류 상태 값 체크
			 */
			function cysnetCnctrClinic(data1, data2) {

				p_probmSttsMlsfcSeCd = data1;
				p_excnBizClSeCd = data2;
				var type = "0";

				if ("14" == p_excnBizClSeCd) {
					if ("0601" == p_probmSttsMlsfcSeCd) { // 자살
						type = "1";
					} else if ("0602" == p_probmSttsMlsfcSeCd) { // 비자살적자해
						type = "2";
					}

					if (sUserId == "mogefsystem" || sUserId == "tssong" || sUserId == "u02tssongad") {
						if (type != "0") {
							if(vcEmbDefInfo1.hasAppMethod("callCnctrClinic")){
								vcEmbDefInfo1.callAppMethod("callCnctrClinic", type);
							}
						}
					}
				}
			}

			function cysnetCnctrClinicDataSet() {
				var dsCaseYngbgs = app.lookup("dsCaseYngbgs");
				var dsBizReg = app.lookup("dsBizReg");

				var sucYn = false; // 자살 0601
				var injYn = false; // 비자살적자해 0602
				var bizYn = false; // 심리클리닉여부

				var type = "0";

				for (var i=0;i<dsCaseYngbgs.getRowCount();i++) {

					if ("0601" == dsCaseYngbgs.getValue(i, "PROBM_STTS_MLSFC_SE_CD")) {
						sucYn = true;
						p_probmSttsMlsfcSeCd = dsCaseYngbgs.getValue(i, "PROBM_STTS_MLSFC_SE_CD");
					}
					if ("0602" == dsCaseYngbgs.getValue(i, "PROBM_STTS_MLSFC_SE_CD")) {
						injYn = true;
						p_probmSttsMlsfcSeCd = dsCaseYngbgs.getValue(i, "PROBM_STTS_MLSFC_SE_CD");
					}
				}

				for (var i=0;i<dsBizReg.getRowCount();i++) {
					if ("14" == dsBizReg.getValue(i, "EXCN_BIZ_CL_SE_CD")) {
						bizYn = true;
						p_excnBizClSeCd = dsBizReg.getValue(i, "EXCN_BIZ_CL_SE_CD");
					}
				}

				if ( (sucYn && bizYn) || (injYn && bizYn) ) {
					if (sucYn) {
						type = "1";
					}

					if (injYn) {
						type = "2";
					}

					if (sucYn && injYn) {
						type = "3";
					}

					if (sUserId == "mogefsystem" || sUserId == "tssong" || sUserId == "u02tssongad") {

						if (type != "0") {
			//				if (vcEmbDefInfo1.app == undefined) {
			//					// 임베디드 값 설정 전에 호출 될 경우 재 호출을 위해.
			//					cysnetCnctrClinicDataSet();
			//				} else {
								setTimeout(setTimeoutCallback, 500, type);

			//				}
						}
					}
				}
			}

